export const COMMON_PASSIVES=[{"id":"WM_Common_SKILL_002","name":"Небесная кара","requiredLevel":130,"description":"После 7 попаданий боевыми умениями цель поражает копьё, наносящее 240% базового урона. Учитывается не более одного попадания за каждое применение умения. Эффект срабатывает не чаще 1 раза в 5 сек. Копьё игнорирует шанс блокирования щитом.\nНе влияет на следующие умения:\n«Гнев природы»\n«Дух сумрака»\n«Дух грозы»\n«Луч погибели»","icon":"icons/mastery/M_ALL_SKILL_12.webp"},{"id":"WM_Common_SKILL_001","name":"Решающий момент","requiredLevel":130,"description":"Если объём здоровья персонажа составляет менее 50% от максимального, на 5 сек. скорость атаки повышается на 20%, а скорость восстановления умений — на 35%. Эффект срабатывает не чаще 1 раза в 60 сек.","icon":"icons/mastery/M_ALL_SKILL_7.webp"},{"id":"WM_Common_SKILL_004","name":"Сделка со смертью","requiredLevel":260,"description":"Время восстановления умений типа «Живучесть» сокращается на 3 сек. при убийстве противника. Эффект срабатывает не чаще 1 раза в 20 сек.","icon":"icons/mastery/M_ALL_SKILL_9.webp"},{"id":"WM_Common_SKILL_003","name":"Противоборство","requiredLevel":260,"description":"Успешная защита от 3 яростных атак в течение 1 сек. создаёт ударную волну радиусом 5 м, которая наносит 100% базового урона и придаёт противникам импульс, отбрасывая их. Эффект срабатывает не чаще 1 раза в 20 сек.","icon":"icons/mastery/M_ALL_SKILL_6.webp"},{"id":"WM_Common_SKILL_006","name":"Душа аспида","requiredLevel":390,"description":"Если персонаж в бою не двигается с места в течение 4 сек., на него на 9 сек. накладывается эффект, аналогичный эффекту умения «Сочащийся яд». Передвижение с помощью умений не нарушает состояние неподвижности. Эффект срабатывает не чаще 1 раза в 60 сек.","icon":"icons/mastery/M_ALL_SKILL_1.webp"},{"id":"WM_Common_SKILL_005","name":"Витализм","requiredLevel":390,"description":"Если объём здоровья персонажа или союзника достигает 30% от максимального объёма или менее, использование активного умения для исцеления на 6 сек. создаёт под персонажем или союзником исцеляющую область радиусом 1 м. Эффект срабатывает не чаще 1 раза в 60 сек.","icon":"icons/mastery/M_ALL_SKILL_11.webp"},{"id":"WM_Common_SKILL_008","name":"Взмывающий дракон","requiredLevel":520,"description":"Когда текущий запас маны персонажа составляет 60% от максимального или более, каждая атака с помощью активного умения дополнительно расходует 4% текущего запаса маны, наносит урон в размере 140% базового урона, а также дополнительно наносит урон в размере 7% текущего запаса маны. Эффект срабатывает не чаще 1 раза за использование умения.\nНе влияет на следующие умения:\n«Гнев природы»\n«Дух сумрака»\n«Дух грозы»\n«Луч погибели»","icon":"icons/mastery/M_ALL_SKILL_8.webp"},{"id":"WM_Common_SKILL_007","name":"Внутренний резерв","requiredLevel":520,"description":"Показатели силы, ловкости, мудрости, восприятия и стойкости повышаются на 1 ед.","icon":"icons/mastery/M_ALL_SKILL_10.webp"},{"id":"WM_Common_SKILL_009","name":"Опадающие лепестки","requiredLevel":650,"description":"После израсходования 10% максимальной маны успешное попадание по цели обрушивает на неё и противников в радиусе 1 м пламя, наносящее 210% базового урона. Эффект срабатывает не чаще 1 раза в 6 сек.","icon":"icons/mastery/M_ALL_SKILL_4.webp"},{"id":"WM_Common_SKILL_010","name":"Непробиваемая стойка","requiredLevel":650,"description":"Если текущий объём здоровья персонажа составляет 90% от максимального или выше в течение 5 сек., при получении урона персонажа на 3 сек. окружает защитный барьер, поглощающий урон в размере показателя стойкости персонажа, умноженного на 120. Эффект срабатывает не чаще 1 раза в 60 сек.","icon":"icons/mastery/M_ALL_SKILL_2.webp"},{"id":"WM_Common_SKILL_011","name":"Молниеносный натиск","requiredLevel":780,"description":"Если персонаж непрерывно движется в течение 10 сек., на персонажа накладывается эффект, который в течение 3 сек. при попадании по противнику вызывает цепную молнию, наносящую 40% базового урона. Если противник находится под действием эффекта «Промок до нитки!» или наложенного персонажем эффекта «Иней», молния дополнительно поражает до 2 противников в радиусе 5 м. Эффект срабатывает не чаще 1 раза в 30 сек.","icon":"icons/mastery/M_ALL_SKILL_3.webp"},{"id":"WM_Common_SKILL_012","name":"Отложенный взрыв","requiredLevel":780,"description":"При каждом использовании умения типа «Атака» на персонажа на 10 сек. накладывается эффект «Отложенный взрыв» (может суммироваться до 3 раз). При нанесении урона с помощью умения типа «Контроль» эффект «Отложенный взрыв» переходит на пораженных противников (до 3), спустя 3 сек. создавая в радиусе 3 м вокруг них взрывы, наносящие гарантированный фиксированный урон в размере 5% максимального объёма здоровья за каждый уровень эффекта. Эффект срабатывает не чаще 1 раза в 30 сек.","icon":"icons/mastery/M_ALL_SKILL_5.webp"}];
